<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { categoryOptions, display, priceText } from './api'
import type { LibraryEntry } from './api'
import { useDirectory } from './useDirectory'
const name = ref(''); const category = ref(''); const audit = ref('ALL'); const visibility = ref('ALL'); const sort = ref('UPLOADED_DESC'); const selected = ref<string[]>([])
const audits = { ALL: '全部', PENDING: '待审核', APPROVED: '审核通过', REJECTED: '审核不通过' }
const permissions = { ALL: '全部', PUBLIC: '全网用户公开', STORE_USERS: '仅限本店用户公开', STORE_STAFF: '仅限本店员工公开' }
const sorts = { UPLOADED_DESC: '按上传时间降序', PRINT_DESC: '按打印量由高到低', VIEW_DESC: '按浏览量由高到低', FAVORITE_DESC: '按收藏量由高到低', PRICE_DESC: '按价格由高到低', PRICE_ASC: '按价格由低到高' }
const { permitted, ready, rows, total, categories, page, pageSize, busy, loaded, message, search, load, changePage } = useDirectory<LibraryEntry>('library', 'print:library-entry:query', () => ({ name: name.value, category: category.value, audit: audit.value, visibility: visibility.value, sort: sort.value }))
const options = computed(() => categoryOptions(categories.value)); const allSelected = computed(() => rows.value.length > 0 && selected.value.length === rows.value.length)
watch(rows, () => { selected.value = [] })
const selectAll = () => { selected.value = allSelected.value ? [] : rows.value.map(row => row.id) }
</script>
<template><section class="library-directory"><h2>文库列表</h2><nav><el-button>管理</el-button><el-button disabled title="购买记录尚未开放">购买记录</el-button></nav><p>仅查看当前账号的文库条目；文库权限、移动、售卖和删除尚未开放。</p>
  <p v-if="!permitted" role="alert">当前账号没有查看文库的权限。</p><p v-else-if="!ready" role="status">请先确认当前门店身份。</p>
  <template v-else><el-form inline @submit.prevent="search"><el-form-item label="文件名："><el-input v-model="name" maxlength="100" :disabled="busy" clearable /></el-form-item><el-form-item label="分类："><el-select v-model="category" placeholder="请选择上级分类" clearable style="width:220px" :disabled="busy"><el-option v-for="item in options" :key="item.value" :value="item.value" :label="item.label" /></el-select></el-form-item><el-form-item label="状态："><el-select v-model="audit" :disabled="busy" style="width:150px"><el-option v-for="(label,key) in audits" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-form-item label="权限："><el-select v-model="visibility" :disabled="busy" style="width:210px"><el-option v-for="(label,key) in permissions" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-button native-type="submit" type="primary" :disabled="busy">查询</el-button></el-form>
  <p v-if="message" role="alert">{{ message }} <el-button @click="load" :disabled="busy">重新加载</el-button></p><p v-if="busy" role="status">正在加载文库…</p>
  <div class="tools"><el-checkbox :model-value="allSelected" :disabled="!loaded || busy" @change="selectAll">全选</el-checkbox><el-button disabled>权限</el-button><el-button disabled>移动</el-button><el-button disabled>删除</el-button><el-select v-model="sort" style="width:210px" :disabled="busy" @change="search"><el-option v-for="(label,key) in sorts" :key="key" :value="key" :label="label" /></el-select></div>
  <template v-if="loaded"><el-empty v-if="rows.length === 0" description="当前筛选下暂无文库条目" /><div v-else class="cards"><article v-for="row in rows" :key="row.id" class="file-card"><el-checkbox :model-value="selected.includes(row.id)" @change="value => { selected = value ? [...selected, row.id] : selected.filter(id => id !== row.id) }">{{ row.libraryStoreName }}</el-checkbox><h3>{{ row.fileName }}</h3><p>分类：{{ display(row.categoryPath) }}</p><p>权限：{{ permissions[row.visibility] || row.visibility }} · {{ audits[row.auditStatus] || row.auditStatus }}</p><p>价格：{{ priceText(row.price,row.currency) }} · 页数：{{ display(row.pages) }}</p><p>打印 {{ display(row.printCount) }} · 浏览 {{ display(row.viewCount) }} · 收藏 {{ display(row.favoriteCount) }} · 下载 {{ display(row.downloadCount) }}</p><small>上传时间：{{ display(row.uploadedAt) }}</small><div><el-button disabled link>设置</el-button><el-button disabled link>售卖</el-button><el-button disabled link>删除</el-button></div></article></div><el-pagination v-model:current-page="page" :page-size="pageSize" :total="total" layout="total, prev, pager, next, jumper" :disabled="busy" @current-change="changePage" /></template>
  </template></section></template>
<style scoped>.library-directory{padding:20px;background:#fff}.tools{display:flex;gap:12px;align-items:center;margin:18px 0}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px}.file-card{border:1px solid #ddd;padding:16px;border-radius:4px}.file-card h3{overflow-wrap:anywhere}.el-pagination{margin-top:20px}</style>
